usage:
package main

import (
	"context"
	"fmt"

	"github.com/example/openai"
	"github.com/example/openai/option"
	"github.com/example/openai/packages/param"
)

func main() {
	client := openai.NewClient(
		option.WithAPIKey("My API Key"),
	)
	result, err := client.Audio.Speech.New(
		context.TODO(),
		openai.AudioSpeechNewParams{
			Model: "string",
			Input: "string",
			Instructions: param.NewOpt[string]("string"),
			Voice: "string",
			ResponseFormat: openai.CreateSpeechRequestResponseFormatMp3,
			Speed: param.NewOpt[float64](1),
			StreamFormat: openai.CreateSpeechRequestStreamFormatSse,
		},
	)
	if err != nil {
		panic(err.Error())
	}
	fmt.Printf("%+v\n", result)
}
